using System.ComponentModel.DataAnnotations;

namespace GameHub.Models.Entities
{
    /// <summary>
    /// A PDF attached to a job offer. Either the system-generated offer letter
    /// (<see cref="IsLetter"/> and <see cref="IsGenerated"/> are true) or a
    /// supporting document uploaded by HR (IsLetter false).
    ///
    /// Files are stored outside wwwroot under a generated filename using the
    /// existing HR document-storage conventions; they are only reachable
    /// through authorized controller actions.
    /// </summary>
    public class JobOfferDocument
    {
        public int Id { get; set; }

        public int JobOfferId { get; set; }

        public JobOffer? JobOffer { get; set; }

        [Required, MaxLength(200)]
        public string StoredFileName { get; set; } = string.Empty;

        [Required, MaxLength(255)]
        public string OriginalFileName { get; set; } = string.Empty;

        [Required, MaxLength(100)]
        public string ContentType { get; set; } = "application/pdf";

        public long FileSize { get; set; }

        // True for the single offer letter, false for supporting documents.
        public bool IsLetter { get; set; }

        // True when the letter was generated by the system, false when uploaded.
        public bool IsGenerated { get; set; }

        [MaxLength(150)]
        public string? Title { get; set; }

        public DateTime CreatedAt { get; set; }
    }
}
